'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
def tr(s): return "".join(code[s[i:i+3]] for i in range(0,len(s)-2,3))
def tr_noStop(s): return "".join(code[s[i:i+3]] for i in range(0,len(s)-3,3))

STARTS = ("ATG","GTG","TTG")
STOPS = ("TAA","TAG","TGA")

# find all ORFs on a strand for given frame: start in STARTS, run to first in-frame stop, or off-end
def orfs_in_frame(s, frame):
    out = []
    L2 = len(s)
    p = frame
    while p < L2-2:
        if s[p:p+3] in STARTS:
            q = p+3
            while q < L2-2:
                if s[q:q+3] in STOPS:
                    out.append((p, q+2, True))   # inclusive end index
                    p = q+3
                    break
                q += 3
            else:
                # ran off the end without a stop
                out.append((p, L2-1 - ((L2-1-p) % 3), False))
                p = L2
        else:
            p += 3
    return out

def report(strand, parent):
    print(f"===== {strand} strand =====")
    all_orfs = []
    for fr in range(3):
        for (p, q, has_stop) in orfs_in_frame(parent, fr):
            all_orfs.append((fr, p, q, has_stop))
    # longest no-stop runway per frame
    for fr in range(3):
        best = (0, None, None)
        cur_start = None
        for p in range(fr, len(parent)-2, 3):
            if parent[p:p+3] in STOPS:
                if cur_start is not None:
                    run = p - cur_start
                    if run > best[0]: best = (run, cur_start, p-1)
                    cur_start = None
            else:
                if cur_start is None: cur_start = p
        if cur_start is not None:
            last = cur_start
            while last + 3 <= len(parent)-1:
                last += 3
            last = min(last, len(parent)-1)
            run = last - cur_start
            if run > best[0]: best = (run, cur_start, last)
        print(f"  frame {fr+1} longest no-stop runway: {best[0]} nt "
              f"({parent[best[1]] if False else best[1]})..({best[2]})" if best[1] is not None else "  frame ? none")
    print("  --- ORFs starting with ATG/GTG/TTG (len>=200 nt), longest first ---")
    for (fr,p,q,has_stop) in sorted(all_orfs, key=lambda x: -(x[2]-x[1])):
        if q-p+1 < 200: continue
        sub = parent[p:q+1]
        prot = tr_noStop(sub)
        if strand == "+":
            f_start, f_end = p+1, q+1
        else:
            f_start, f_end = L-q, L-p
        print(f"   start={parent[p:p+3]} stop={'yes' if has_stop else 'NO (runs off end)'} "
              f"frame={fr+1} nt({strand}, 1-based)={f_start}..{f_end} len_nt={q-p+1} aa={len(prot)} "
              f"prot[:18]={prot[:18]} prot[-8:]={prot[-8:]}")
    print()

